# Payments/Unit4.dfm:5 ODSPayments (TOracleDataSet)
SQL_PAY_ODSPAYMENTS = "select * from (\nSELECT a.id,nvl((select filial from account where id= (select accid from ibank_client_products where id=a.from_accid)),-1)as filial , a.amount, a.bank_acc, a.bank_bic, a.bank_code, a.bank_name, a.bank_tin,a.currency,\n a.descreption||'**'||a.note as descreption,\n       a.pay_date,a.receiver_bank_acc, a.receiver_bank_bic, a.receiver_bank_code,a.receiver_bank_name, a.receiver_bank_tin,\n       a.receiver_tin,a.transaction_type,a.cli_id, a.status, a.pin1, a.pin2, a.trans_id, a.susdat,\n     case when a.transaction_type=1  then 'Bank daxili'\n          when a.transaction_type=2  then 'AZIPS'\n          when a.transaction_type=3  then 'Konvertasiya'\n          when a.transaction_type=4 then 'X.O.H.K.S'\n          when a.transaction_type=5 then 'X.O.H.K.S (Büdcə)'\n          when a.transaction_type=7  then 'Hesablar arasi'\n          when a.transaction_type=8 then 'Emekhaqqi'\n          when a.transaction_type=9 then 'Xarici kocurmeler'\n          end as tr_type,\n\n  (select accno from ibank_client_products  where id=a.from_accid) as  gonderen_acc ,\n    case when a.transaction_type in(3,7) then\n          decode ((select accno from ibank_client_products  where id=a.to_accid),null, receiver_acc,-1,receiver_acc,\n                  (select accno from ibank_client_products  where id=a.to_accid))\n                  else a.receiver_acc end as alan_acc ,\n    case when a.transaction_type in(3,7) then\n                  decode ((select defaultname from ibank_client_products  where id=a.to_accid),null, receiver_name,-1,receiver_name,\n                          (select defaultname from ibank_client_products  where id=a.to_accid))\n                  else a.receiver_name end as  alan_name,\n   (select defaultname from ibank_client_products  where id=a.from_accid) as  gonderen_name ,\n    case when a.transaction_type in(3,7) then\n                  decode ((select acctin from ibank_client_products  where id=a.to_accid),null, receiver_tin,-1,receiver_tin,\n                          (select acctin from ibank_client_products  where id=a.to_accid))\n                  else a.receiver_tin end as  alan_inn,\n  (select acctin from ibank_client_products  where id=a.from_accid)           as  gonderen_inn\n   FROM ibank_temp_transaction a ,ibank_client_products c,ibank_client_products c1\n   where  c.id(+)= a.to_accid and c1.id(+)= a.from_accid and transaction_type not in(44,55,88) and  a.trans_id is not null\n\nAND    (trunc(a.susdat)) >=:DAT1 AND  pay_date <=:DAT2 and a.status not in (0,9,10)\n\n\n)\n\n\n\n\n\n\n--order by transaction_type\n order by :sort\n"

# Payments/Unit4.dfm:246 dsfilials (TOracleDataSet)
